import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.platform.InMemoryTransactionManager;
import com.wolinski.shop.shipping.api.CarrierGateway;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;

class OrderConfirmationTest {

    /** Records every booking and whether a transaction was open at the time of the call. */
    static class FakeCarrier implements CarrierGateway {
        final List<String> bookedOrders = new ArrayList<>();
        final List<Boolean> bookedInsideTransaction = new ArrayList<>();
        RuntimeException failure;

        @Override
        public String book(String orderId) {
            bookedInsideTransaction.add(InMemoryTransactionManager.isOpen());
            if (failure != null) {
                throw failure;
            }
            bookedOrders.add(orderId);
            return "TRK-" + orderId;
        }
    }

    static class FakeCarrierConfig {
        @Bean
        @Primary
        FakeCarrier fakeCarrier() {
            return new FakeCarrier();
        }
    }

    @Test
    void confirmingBooksAShipmentAndStoresTheTrackingNumber() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class, FakeCarrierConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            FakeCarrier carrier = shop.getBean(FakeCarrier.class);

            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            assertNull(orders.summary(id).trackingNumber());

            orders.confirm(id);

            assertEquals(List.of(id), carrier.bookedOrders);
            assertEquals(List.of(false), carrier.bookedInsideTransaction, "carrier must be called outside a transaction");
            var summary = orders.summary(id);
            assertEquals("CONFIRMED", summary.status());
            assertEquals("TRK-" + id, summary.trackingNumber());
        }
    }

    @Test
    void confirmingTwiceBooksOnlyOnce() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class, FakeCarrierConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            FakeCarrier carrier = shop.getBean(FakeCarrier.class);

            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            orders.confirm(id);
            orders.confirm(id);

            assertEquals(1, carrier.bookedOrders.size());
        }
    }

    @Test
    void aFailedBookingLeavesTheOrderConfirmedWithoutTrackingAndReachesTheCaller() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class, FakeCarrierConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            FakeCarrier carrier = shop.getBean(FakeCarrier.class);
            carrier.failure = new IllegalStateException("carrier down");

            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            var error = assertThrows(IllegalStateException.class, () -> orders.confirm(id));

            assertEquals("carrier down", error.getMessage());
            assertTrue(!InMemoryTransactionManager.isOpen());
            var summary = orders.summary(id);
            assertEquals("CONFIRMED", summary.status());
            assertNull(summary.trackingNumber());
        }
    }
}
}
